"""Verify delivered inventory counts; no network, runtime imports or production approval."""
import csv,json,pathlib,sqlite3,xml.etree.ElementTree as ET
p=pathlib.Path(__file__).resolve().parent
def rows(n):return list(csv.DictReader((p/n).open()))
e=json.loads((p/'evidence.json').read_text());c=rows('connector-catalog.csv');db=sqlite3.connect(':memory:');db.execute('create table c(id,vendor,category)');db.executemany('insert into c values(?,?,?)',[(r['id'],r['vendor_label'],r['system_class']) for r in c]);assert db.execute('select count(*),count(distinct id),count(distinct vendor),count(distinct category) from c').fetchone()==(e['catalog_entries'],e['distinct_catalog_ids'],e['raw_vendor_labels'],e['system_classes']);assert len(rows('capability-map.csv'))==e['capability_families'];assert len(rows('api-inventory.csv'))==e['declared_api_interfaces'];assert len(rows('package-identities.csv'))==e['package_identities'];root=rows('root-coverage.csv');assert len(root)==len({r['path'] for r in root})==e['root_entries'];xml=ET.parse(p/'catalog-tests.xml');assert len(xml.findall('.//testcase'))==e['fresh_catalog_tests'];assert not xml.findall('.//failure') and not xml.findall('.//error');print('PASS: inventory and JUnit consistency; production/publication HOLD unchanged')
